 3→test.describe('Theme toggle switches between light and dark', () => {
 4→  test('should start in light mode and switch to dark mode on toggle click', async ({ page }) => {
 5→    await page.goto('/');
 6→
 7→    const themeToggle = page.getByTestId('theme-toggle');
 8→    await expect(themeToggle).toBeVisible();
 9→
10→    // Default theme should be light
11→    const tuiRoot = page.locator('tui-root');
12→    await expect(tuiRoot).toHaveAttribute('tuitheme', 'light');
13→
14→    // The toggle should offer to switch to dark
15→    await expect(themeToggle).toHaveAttribute('aria-label', 'Switch to dark theme');
16→
17→    // Click the toggle to switch to dark theme
18→    await themeToggle.click();
19→
20→    // Theme should now be dark
21→    await expect(tuiRoot).toHaveAttribute('tuitheme', 'dark');
22→    await expect(themeToggle).toHaveAttribute('aria-label', 'Switch to light theme');
23→
24→    // Click again to switch back to light theme
25→    await themeToggle.click();
26→
27→    // Theme should be light again
28→    await expect(tuiRoot).toHaveAttribute('tuitheme', 'light');
29→    await expect(themeToggle).toHaveAttribute('aria-label', 'Switch to dark theme');
30→  });
31→
32→  test('should visually change CSS custom properties when toggling theme', async ({ page }) => {
33→    await page.goto('/');
34→
35→    const tuiRoot = page.locator('tui-root');
36→    const themeToggle = page.getByTestId('theme-toggle');
37→
38→    // Capture a theme-dependent CSS custom property in light mode
39→    const lightText = await tuiRoot.evaluate(
40→      (el) => getComputedStyle(el).getPropertyValue('--gt-text').trim(),
41→    );
42→
43→    // Switch to dark mode
44→    await themeToggle.click();
45→
46→    // Capture the same property in dark mode
47→    const darkText = await tuiRoot.evaluate(
48→      (el) => getComputedStyle(el).getPropertyValue('--gt-text').trim(),
49→    );
50→
51→    // The text color variable must differ between themes
52→    expect(lightText).not.toEqual(darkText);
53→  });
54→});
